export function createOptions() {
  const state = { parent: false, child: false };
  return {
    state,
    isChildDisabled: () => !state.parent,
    setParent(value) { state.parent = Boolean(value); },
    setChild(value) { state.child = Boolean(value); },
    clear() { state.parent = false; state.child = false; },
    payload() { return { process: state.parent, research: state.child }; }
  };
}

