import test from 'node:test';
import assert from 'node:assert/strict';
import { createOptions } from '../src/options.mjs';
test('初始从属项禁用且未选', () => {
  const options = createOptions();
  assert.equal(options.isChildDisabled(), true);
  assert.equal(options.state.child, false);
});

